int slices = Math.min(workers, amounts.size());   // no idle threads
int base = amounts.size() / slices;
int extra = amounts.size() % slices;               // the first `extra` slices get one more

int from = 0;
for (int w = 0; w < slices; w++) {
    int start = from, end = start + base + (w < extra ? 1 : 0), slot = w;
    // 1. each worker sums its own slice into its own slot
    threads[w] = new Thread(() -> {
        long sum = 0;
        for (int i = start; i < end; i++) sum += amounts.get(i);
        partial[slot] = sum;
    }, "ledger-worker-" + w);
    threads[w].start();
    from = end;
}

